INSERT INTO quizzes (id, course_id, title, description, passing_score, duration_minutes)
SELECT gen_random_uuid(), id,
'Market Opportunity Assessment - agro-forestry',
'Validate your readiness in business validation for Market Opportunity',
70.0, 15
FROM courses WHERE id = 'agro-forestry' LIMIT 1;

INSERT INTO quiz_questions (id, quiz_id, question_text, question_type, options, correct_answer, explanation, order_number)
SELECT gen_random_uuid(),
(SELECT id FROM quizzes WHERE title = 'Market Opportunity Assessment - agro-forestry' ORDER BY created_at DESC LIMIT 1),
'What is your target market size estimate?',
'multiple_choice',
'["$100K", "$1M", "$10M", "Over $10M"]'::jsonb,
'$10M',
'Know your addressable market',
1
FROM courses WHERE id = 'agro-forestry' LIMIT 1;

